// Single navigation owner: historical modules register lifecycle hooks, never replace showTab.
const PS_NAV_TABS=Object.freeze(['overview','evidence','search','interview','timeline','inspection12','notebook','labs','deduction','final']);
const PS_NAV_HOOKS=[];
function registerNavigationHook(spec){
 if(!spec || typeof spec.name!=='string' || !spec.name.trim() ||
   (typeof spec.before!=='function' && typeof spec.after!=='function'))throw Error('Nieprawidłowy hook nawigacji');
 if(PS_NAV_HOOKS.some(h=>h.name===spec.name))throw Error('Powtórzony hook nawigacji: '+spec.name);
 const hook=Object.freeze({name:spec.name,before:spec.before,after:spec.after});
 PS_NAV_HOOKS.push(hook);
 return ()=>{const index=PS_NAV_HOOKS.indexOf(hook);if(index>=0)PS_NAV_HOOKS.splice(index,1);};
}
function showTab(id){
 if(!PS_NAV_TABS.includes(id) || !document.getElementById(id)?.classList.contains('section'))return false;
 const context={id,previousTab:STATE.tab};
 // Former nested wrappers performed their "before" work from outermost to innermost.
 const hooks=PS_NAV_HOOKS.slice();
 for(let i=hooks.length-1;i>=0;i--)if(hooks[i].before)hooks[i].before(context);
 STATE.tab=id;
 document.querySelectorAll('.section').forEach(e=>e.classList.toggle('active',e.id===id));
 document.querySelectorAll('.nav button[data-tab]').forEach(b=>{
  const active=b.dataset.tab===id;
  b.classList.toggle('active',active);
  if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');
 });
 if(id==='evidence')renderDocs();
 if(id==='interview')renderChat();
 if(id==='timeline'){renderEvents();tlRender();}
 if(id==='deduction')dedRender();
 if(id==='inspection12'){scMarkRoom();scRender();}
 if(id==='final')fcRender();
 if(id==='notebook')scRenderNotebook();
 if(id==='labs'){tcmsRefresh();msgRefresh();cctvRefresh();forensicRefresh();accessRefresh();}
 if(id==='labs'&&window.stage3)window.stage3.render();
 window.scrollTo({top:0,behavior:'instant'});
 // The same order as before: innermost wrapper finished before the outer wrappers.
 for(const hook of hooks)if(hook.after)hook.after(context);
}
function psBindNavigation(){
 document.querySelectorAll('[data-tab],[data-go]').forEach(button=>{
  button.addEventListener('click',()=>{
   if(button.disabled || button.getAttribute('aria-disabled')==='true')return;
   showTab(button.dataset.tab||button.dataset.go);
  });
 });
}
