function getEvidenceType(material){
 const label=norm(material.title);
 // Dokumentacja administracyjna nie staje się zeznaniem tylko dlatego, że leży w teczce „zeznania”.
 if(/\b(zeznan|przesluchan|oswiadczen|relacj[aie])/.test(label))return 'testimony';
 // Mikroślady i ich analizy stanowią odrębną kategorię dowodów rzeczowych.
 if(material.category==='laboratoryjne/mikroślady')return 'trace';
 // Fotograficzne zabezpieczenia miejsca i rzeczy, a nie każdy plik wideo z CCTV.
 if(material.category==='wizualne/CCTV'&&material.acquisition==='oględziny'&&/\b(zdjecie|fotografi)/.test(label))return 'trace';
 return 'document';
}
