function renderAreas(){$('areas').innerHTML=AREAS.map(a=>`<button class="location ${a.id===STATE.area?'selected':''}" data-area="${a.id}"><b>${esc(a.title)}</b><span>${esc(a.desc)}</span></button>`).join('');$('areas').querySelectorAll('[data-area]').forEach(b=>b.addEventListener('click',()=>{STATE.area=b.dataset.area;renderAreas();$('searchResults').textContent='Wpisz, czego szukasz w tym obszarze.';}));}
const PS_GENERIC=new Set(['karta','raport','rejest','zapis','protok','dokume','lista','wydruk','zglosz','polece','system','wiadom','serwis']);
function scoreDoc(q,d){const qt=tokens(q).filter(t=>!PS_GENERIC.has(t)),dt=tokens(d.title+' '+d.id);if(!qt.length)return 0;let m=0;for(const t of qt){if(dt.some(x=>x.startsWith(t)||t.startsWith(x)))m++;}let score=m/qt.length;if(qt.length>1&&m<2)score*=.5;if(norm(d.title).includes(norm(q))&&norm(q).length>5)score+=1;return score;}
function searchArea(){const q=$('searchQuery').value.trim(),box=$('searchResults');if(q.length<4){box.textContent='Wpisz bardziej konkretny przedmiot poszukiwań.';return;}if(!tokens(q).some(t=>!PS_GENERIC.has(t))){box.textContent='To zbyt ogólne określenie. Nazwij konkretny przedmiot, system, osobę lub miejsce.';return;}
const possible=DOCS.filter(d=>d.area===STATE.area&&searchCanAcquire(d)&&!STATE.found.has(d.id)&&!sceneDocBlocked(d.id)).map(d=>({d,sc:scoreDoc(q,d)})).filter(x=>x.sc>=.43).sort((a,b)=>b.sc-a.sc);
if(!possible.length){const locked=DOCS.filter(d=>d.area===STATE.area&&searchCanAcquire(d)&&!STATE.found.has(d.id)&&sceneDocBlocked(d.id)).map(d=>({d,sc:scoreDoc(q,d)})).filter(x=>x.sc>=.43).sort((a,b)=>b.sc-a.sc);if(locked.length){box.textContent='Najpierw zdobądź wcześniejsze ustalenia: '+scDocMissing(locked[0].d.id).map(id=>byId[id]?.title||id).join('; ')+'. Możesz je zbadać również podczas oględzin zajezdni.';return;}box.textContent='Nie odnaleziono nowego materiału spełniającego to kryterium w wybranym obszarze. Możesz sprawdzić inne źródło lub użyć precyzyjniejszego określenia.';return;}
const pick=possible[0].d;STATE.found.add(pick.id);PS_EVENTS.evidence(pick.id,'area-search');activeDoc=pick.id;box.innerHTML=`<b style="color:var(--green)">Zabezpieczono materiał:</b> ${esc(pick.title)} <span class="muted small">(${esc(evDisplayRef(pick))})</span> <button class="btn alt" id="openAcquired" style="margin-left:9px">Odczytaj</button>`;$('openAcquired').addEventListener('click',()=>showTab('evidence'));renderCounts();renderAttached();tcmsRefresh();msgRefresh();cctvRefresh();forensicRefresh();accessRefresh();toast('Do akt dodano: '+pick.title);}
