function npc8Initials(name){return String(name||'').split(/\s+/).filter(Boolean).slice(0,2).map(w=>w[0]).join('');}
function npc8GetState(c){
 const fallback={rapport:34,tension:28,fatigue:12,stance:'neutral',mood:'rzeczowy'};
 let st=fallback;
 try{if(typeof NPC4_STATE!=='undefined'&&NPC4_STATE&&NPC4_STATE[c.id])st=NPC4_STATE[c.id];}catch(err){}
 const rapport=Math.round(Math.max(0,Math.min(100,st.rapport??fallback.rapport)));
 const tension=Math.round(Math.max(0,Math.min(100,st.tension??fallback.tension)));
 const fatigue=Math.round(Math.max(0,Math.min(100,st.fatigue??fallback.fatigue)));
 const f=c.gender==='f';let mood=f?'rzeczowa':'rzeczowy',cls='is-neutral';
 if(fatigue>=68){mood=f?'zmęczona':'zmęczony';cls='is-tired';}
 else if(tension>=76){mood=f?'spięta':'spięty';cls='is-tense';}
 else if((st.stance==='firm'&&tension>=58)||tension>=60){mood='na dystans';cls='is-guarded';}
 else if(rapport>=58&&tension<55){mood=f?'bardziej otwarta':'bardziej otwarty';cls='is-open';}
 const last=(STATE.dialogues[c.id]||[]).slice(-1)[0];
 return {rapport,tension,fatigue,mood,cls,speaking:last&&last.role==='npc'?'is-speaking':'',stance:st.stance||'neutral'};
}
