// RC57.10.17 — fotografie fikcyjnych świadków z wybranego projektu "Akta Śledcze".
// Identyfikatory to stała allowlista, nie dane od gracza; ścieżki są lokalne.
const NPC8_PHOTOS=Object.freeze({
 MAREK:'marek.webp',TOMASZ:'tomasz.webp',JANUSZ:'janusz.webp',
 ELZBIETA:'elzbieta.webp',KAMIL:'kamil.webp',MAGDALENA:'magdalena.webp'
});
function npc8PortraitPhoto(id,mini=false){
 const file=NPC8_PHOTOS[id];if(!file)return '';
 return `<img class="wp-photo" src="assets/portraits/${file}" alt="" ${mini?'loading="lazy" fetchpriority="low"':'loading="lazy" fetchpriority="high"'} decoding="async" draggable="false" aria-hidden="true">`;
}
function npc8PortraitMarkup(c,mini=false){
 const p=NPC8_PORTRAITS[c.id]||NPC8_PORTRAITS.MAREK,st=npc8GetState(c);
 const hostClass=(mini?'wp-mini ':'wp-stage ')+st.cls+' '+st.speaking;
 const vars=`--wp-bg1:${p.bg1};--wp-bg2:${p.bg2};--wp-delay:-${(Object.keys(NPC8_PORTRAITS).indexOf(c.id)+1)*.7}s;`;
 // The old SVG stays underneath as a lossless fallback and keeps face-controller hooks.
 const layers=npc8PortraitSvg(c,mini,st)+npc8PortraitPhoto(c.id,mini);
 if(mini)return `<div class="${hostClass}" data-witness="${c.id}" style="${vars}" aria-hidden="true">${layers}<span class="wp-mini-status"></span></div>`;
 return `<div class="${hostClass}" data-witness="${c.id}" style="${vars}"><div class="wp-picture" role="img" aria-label="${esc('Fotograficzny portret: '+c.name+'. Stan rozmowy: '+st.mood)}">${layers}<div class="wp-topline" aria-hidden="true"><span><i class="wp-signal"></i> SALA PRZESŁUCHAŃ</span><span class="wp-initials">${esc(npc8Initials(c.name))}</span></div></div></div>`;
}
function npc8RefreshWitnessPortrait(){
 const c=CONTENT.characters.find(x=>x.id===STATE.activeChar);
 if(!c)return;
 const host=$('witnessStage'); if(host) host.innerHTML=npc8PortraitMarkup(c,false);
 const quick=$('witnessQuickState');
 if(quick){
   const st=npc8GetState(c);
   quick.innerHTML='<b>REAKCJA</b><span>'+(st.cls==='is-open'?'Świadek odpowiada swobodniej. Możesz doprecyzować jego relację.':st.cls==='is-tense'?'Nacisk może utrudnić uzyskanie precyzyjnej odpowiedzi.':st.cls==='is-tired'?'Długa rozmowa osłabia precyzję odpowiedzi.':'Obserwuj, czy ton rozmowy nie zmienia postawy świadka.')+'</span>';
 }
 window.PS622_FACES?.refreshCurrent?.();
}
let psWitnessSignature=null,psWitnessFirst=null;
function renderCharacterList(){const list=$('characterList');
 // SVG gradients receive fresh generated IDs on every creation; comparing the
 // final markup would always miss. Base the early exit on actual witness state.
 const signature=JSON.stringify([STATE.activeChar,...CONTENT.characters.map(c=>{
  const st=npc8GetState(c);return [c.id,st.rapport,st.tension,st.fatigue,st.stance,st.mood,st.cls,st.speaking,
   (STATE.dialogues[c.id]||[]).some(m=>m.role==='player')];
 })]);
 if(signature===psWitnessSignature && psWitnessFirst===list.firstChild && list.firstChild)return;
 const markup=CONTENT.characters.map(c=>{const st=npc8GetState(c);return `<button class="character ${c.id===STATE.activeChar?'active':''}" data-char="${c.id}" aria-pressed="${c.id===STATE.activeChar}">${npc8PortraitMarkup(c,true)}<span class="charactercopy"><b>${esc(c.name)}</b><small>${esc(c.role)}</small><span class="ps23-witness-status">${c.id===STATE.activeChar?'Przesłuchiwany':(STATE.dialogues[c.id]||[]).some(m=>m.role==='player')?'Rozmowa rozpoczęta':'Wybierz świadka'}</span></span></button>`;}).join('');psRenderMarkup(list,markup);psWitnessSignature=signature;psWitnessFirst=list.firstChild;list.querySelectorAll('[data-char]').forEach(b=>b.addEventListener('click',()=>{STATE.activeChar=b.dataset.char;renderChat();}));}
// A document in the initial dossier is not yet a witness-confrontation exhibit.
// It becomes available only after a deliberate read in Akta. Newly secured
// documents are available immediately. No unrecovered evidence is ever listed.
function interviewEvidenceAvailable(d){return STATE.found.has(d.id)&&(!INITIAL.includes(d.id)||STATE.reviewedEvidence.has(d.id));}
function renderAttached(){
 const select=$('attachedDoc'),current=select.value,available=DOCS.filter(interviewEvidenceAvailable);
 const options='<option value="">'+(available.length?'Nie okazuj dowodu':'Brak przygotowanych dowodów — przejrzyj Akta')+'</option>'+available.map(d=>`<option value="${esc(d.id)}">${esc(d.title)}</option>`).join('');
 psRenderMarkup(select,options);
 if(available.some(d=>d.id===current))select.value=current;
 // A dossier preview may only show evidence the player has already obtained and
 // consciously reviewed. It reuses the original #attachedDoc selector.
 const cards=document.getElementById('ps23EvidenceCards');
 if(cards){
  const markup=available.length?available.slice(0,3).map((d,i)=>`<button type="button" class="ps23-evidence-card ${select.value===d.id?'selected':''}" data-ps23-exhibit="${esc(d.id)}" aria-label="Okaż dowód: ${esc(d.title)}" aria-pressed="${select.value===d.id}"><span class="ps23-evidence-mini" aria-hidden="true">${esc(d.id.replace(/[^A-Za-z0-9-]/g,'').slice(-8))}</span><span>${esc(d.title)}</span></button>`).join(''):'<p class="ps23-evidence-empty">Dowody do okazania pojawią się tutaj po ich zdobyciu i przejrzeniu w Aktach.</p>';
  if(!psRenderMarkup(cards,markup))return;
  cards.querySelectorAll('[data-ps23-exhibit]').forEach(b=>b.addEventListener('click',()=>{select.value=b.dataset.ps23Exhibit;renderAttached();select.dispatchEvent(new Event('change',{bubbles:true}));}));
 }
}

function inferTone(q){const s=norm(q);if(/przeprasz|wybacz|nie bylo fair|cofam oskarz/.test(s))return 'apology';if(/przykro mi|wspolczuje|musi byc ciezko|jak sie czuj/.test(s))return 'empathy';if(/nie krec|klamiesz|do cholery|przestan klamac|wyrzuce|stracisz prace|zamkn|gadal/.test(s))return 'pressure';return 'neutral';}
function inferTopics(q){const s=norm(q);let result=[];const add=(topic,rx)=>{if(rx.test(s)&&!result.includes(topic))result.push(topic);};add('alibi',/alibi|gdzie (byl|byla|jestes)|co robil|co robilas|co robiles|w jakim miejscu|gdzie sie znajdow/);add('witness',/kto cie (widzial|widzal)|kto potwierdz|kto za (ciebie|pana|pania) reczy|czy ktos.*widzial|ma.*swiadk/);add('last_seen',/ostatni raz|ostatnio (widzial|widziales|widzialas)|kiedy widzial|kiedy rozmawial.*lena/);add('what_happened',/co sie (stalo|wydarzylo)|co wiesz o sprawie|co pan wie o sprawie|co pani wie o sprawie|co wiadomo o sprawie|jak (zginela|zmarla)|co zaszlo|jak to wygladalo/);add('motive',/motyw|powod.*smier|kto zabil|kto mogl (zabic|chciec)|kto zyskal|dlaczego ktos/);add('empathy',/co czuj|jak sie czujesz|ruszylo cie|jest ci przykro|trudno ci|przezywasz|jak to przezy|co pomysl/);if(!result.length){if(/lena|smierc|zabojstw|traged|ofiar/.test(s))result.push('what_happened');else if(/praca|stanowisko|obowiaz|zajmuj|twoja rola/.test(s))result.push('opening');}return result.slice(0,2);}
function makeAnswer(c,q,evid){const voice=c.voice,tone=inferTone(q),topics=inferTopics(q);let prefix='',responses=[];
if(tone==='apology')prefix=voice.apology+' ';else if(tone==='pressure')prefix=voice.pressure+' ';else if(tone==='empathy'&&!topics.includes('empathy'))prefix=voice.empathy+' ';
let gate=null;if(evid&&STATE.found.has(evid))for(const g of CONTENT.gates){if(g.character===c.name&&g.needs.includes(evid)&&g.needs.every(x=>STATE.found.has(x))&&new Set(g.needs.map(x=>(byId[x]||{}).family).filter(Boolean)).size>=g.families){gate=g;break;}}
if(evid){
 const displayed=byId[evid];
 const photo=!!displayed&&(/fotografi|zdjecie|kadr/.test(norm(displayed.title))||/wizualne/i.test(displayed.category||''));
 const photoScope='To jest fotografia: „'+docName(evid)+'”. Pokazuje stan z chwili wykonania zdjęcia; bez dodatkowej chronologii nie przesądza stanu sprzed przyjazdu ratowników ani tożsamości osoby.';
 responses.push(gate?voice.evidence_strong:photo?photoScope:voice.evidence_weak);
 if(gate)return responses[0];
}
for(const topic of topics){if(voice[topic]&&!responses.includes(voice[topic]))responses.push(voice[topic]);}
if(!responses.length){if(tone==='apology'||tone==='pressure'||tone==='empathy')return prefix.trim();return voice.unclear;}
const result=(prefix+responses.join(' ')).trim();return result.length?result:voice.unclear;
}
