const NPC9_NOISE=/^(?:(?:tak po ludzku|sluchaj pytam serio|no dobra|sluchaj no|pytam serio|bez sciemy|powiedz po ludzku)\s+)+/;
function npc9Terms(s){return norm(s).replace(NPC9_NOISE,'').split(' ').filter(w=>w.length>2).map(w=>w.slice(0,5));}
function npc9Grams(s){const q=(' '+norm(s).replace(NPC9_NOISE,'')+' ');const grams=new Set();for(let j=0;j<q.length-2;j++){grams.add(q.slice(j,j+3));}return grams;}
const NPC9_BANK=NPC9_CORPUS.map(([q,t])=>({t, grams:npc9Grams(q), terms:new Set(npc9Terms(q))}));
function npc9Nearest(s){const qg=npc9Grams(s), qt=new Set(npc9Terms(s));if(qg.size<5)return null;
 let first={score:0,t:null}, second={score:0,t:null};
 for(const d of NPC9_BANK){let inter=0;for(const g of qg)if(d.grams.has(g))inter++;const cscore=(2*inter)/(qg.size+d.grams.size);let same=0;for(const t of qt)if(d.terms.has(t))same++;const wscore=qt.size+d.terms.size?2*same/(qt.size+d.terms.size):0;const score=.72*cscore+.28*wscore;
  if(score>first.score){second=first;first={score,t:d.t};}else if(score>second.score){second={score,t:d.t};}}
 return {...first,runner:second};}
